def _config_command() -> None:
    """Show the application's configuration as JSON.

    Sensitive values are masked before output.
    """
    config = {
        key: "***"
        if any(name in key.upper() for name in ("SECRET", "PASSWORD", "TOKEN", "KEY"))
        else value
        for key, value in current_app.config.items()
    }
    click.echo(json.dumps(config, sort_keys=True, default=str))


config_command = click.command("config", short_help="Show the app's configuration.")(
    with_appcontext(_config_command)
)
